solution.code:
import numpy as np

x, y = 1.5, 1.0

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def loss(w, b):
    return (sigmoid(w * x + b) - y) ** 2

def grad(w, b):
    a = sigmoid(w * x + b)
    dz = 2 * (a - y) * a * (1 - a)
    return dz * x, dz

print(grad(0.5, 0.1))
